import { theme } from 'theme';

export const HORIZONTAL_TOTAL_LABEL_OFFSET = 8;
export const HORIZONTAL_TOTAL_LABEL_BUFFER = 4;
export const MIN_HORIZONTAL_TOTAL_LABEL_RESERVED_WIDTH = 48;
export const ESTIMATED_CHAR_WIDTH_PX = 7;

export const formatTotalAllocationLabel = (
  value: string | number,
  unit?: string,
): string => {
  const stringValue = String(value ?? '0.0');

  if (stringValue.includes('$') || !unit) {
    return stringValue;
  }

  return `${unit}${stringValue}`;
};

const measureLabelWidth = (label: string): number => {
  if (typeof document !== 'undefined') {
    try {
      const canvas = document.createElement('canvas');
      const context = canvas.getContext('2d');

      if (context) {
        context.font = theme.fonts.body.xsmall;
        return context.measureText(label).width;
      }
    } catch {
      // jsdom without canvas support falls back to character estimate
    }
  }

  return label.length * ESTIMATED_CHAR_WIDTH_PX;
};

export const getHorizontalTotalLabelReservedWidth = (total_allocation: {
  value: (string | number)[];
  unit?: string;
}): number => {
  const values = total_allocation.value.flatMap((value) =>
    Array.isArray(value) ? value : [value],
  );

  if (values.length === 0) {
    return MIN_HORIZONTAL_TOTAL_LABEL_RESERVED_WIDTH;
  }

  const maxTextWidth = Math.max(
    ...values.map((value) =>
      measureLabelWidth(
        formatTotalAllocationLabel(value, total_allocation.unit),
      ),
    ),
  );

  return Math.max(
    MIN_HORIZONTAL_TOTAL_LABEL_RESERVED_WIDTH,
    Math.ceil(
      maxTextWidth +
        HORIZONTAL_TOTAL_LABEL_OFFSET +
        HORIZONTAL_TOTAL_LABEL_BUFFER,
    ),
  );
};
